input.command:
mkdir -p /app/w && cat > /app/w/p.py <<'EOF'
import json,sys
d=json.load(open(sys.argv[1]))
if 'result' in d and isinstance(d['result'],str): d=json.loads(d['result'])
for m in d.get('messages',[]):
  print(m.get('ts'),m.get('time'), (m.get('user_profile') or {}).get('real_name') or m.get('user') or m.get('username'), (m.get('channel_info') or {}).get('name',''), 'replies=%s'%m.get('reply_count',''), ':', m.get('text','').replace('\n',' / '))
  for f in m.get('files',[]) or []: print('   FILE',f.get('id'),f.get('name'))
  print()
EOF
echo ok

